import numpy as np, json
R=np.load('R.npy'); n=json.load(open('n.json')); T=len(R)
sh=lambda x: x.mean(0)/x.std(0)*np.sqrt(252)
vol=R.std(0)
def rules(A):
    s=sh(A); out={}
    for k in [10,25,50,100]:
        o=np.argsort(-np.abs(s))[:k]; w=np.zeros(len(s)); w[o]=np.sign(s[o])/vol[o]; out[f'top{k}']=w
    out['allsign']=np.sign(s)/vol
    out['shrink']=s/vol
    # ridge MV
    C=np.cov(A.T); mu=A.mean(0)
    for lam in [1,10,100]:
        w=np.linalg.solve(C+lam*np.trace(C)/len(C)*np.eye(len(C)),mu); out[f'ridge{lam}']=w
    return out
# walk-forward with expanding windows: train on years [0,t), test on [t,t+5y)
yr=T/30
res={}
for t in range(10,30,5):
    a=int(t*yr); b=int(min(30,t+5)*yr)
    for k,w in rules(R[:a]).items():
        res.setdefault(k,[]).append(sh(R[a:b]@w))
for k,v in res.items(): print(k, np.round(v,2), round(np.mean(v),2))
